rows=[dict(key='grss',authors='Rahil Makadia; Davide Farnocchia; Steven R. Chesley; Siegfried Eggl',year=2025,
           title='Gauss-Radau Small-body Simulator (GRSS): An Open-source Library for Planetary Defense',
           journal='The Planetary Science Journal',volume='6',page='85',url='https://doi.org/10.3847/PSJ/adbc88',
           metadata_verified=True,role='Primary article and Gaia covariance code inspected; repository commit pinned in source ledger')]
(R/'records/references_reconstruction.json').write_text(json.dumps(rows,indent=2)+'\n')
